exercise.solution:
import re

# group 1: local part; group 2: domain ending in dot + 2+ letters
_EMAIL = re.compile(r"([a-z0-9._-]+)@([a-z0-9.-]+\.[a-z]{2,})")


def redact_emails(text):
    """Mask every local part to first char + '***', keep domains."""
    return _EMAIL.sub(
        lambda m: m.group(1)[0] + "***@" + m.group(2),
        text,
    )

